import{_ as a,o,c as r,ae as t}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"GCP: hierarchy, audiences, and access","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1917971986/references/gcp.md","filePath":"adrs/1917971986/references/gcp.md"}'),n={name:"adrs/1917971986/references/gcp.md"};function i(s,e,c,l,d,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="gcp-hierarchy-audiences-and-access" tabindex="-1">GCP: hierarchy, audiences, and access <a class="header-anchor" href="#gcp-hierarchy-audiences-and-access" aria-label="Permalink to &quot;GCP: hierarchy, audiences, and access&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-10.</p><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><p>The Google Cloud resource hierarchy has three typed levels: the organization at the root, folders as an optional grouping mechanism beneath it, and projects as the fundamental organizing entity that actually contains service resources. Organizations, folders, and projects are all typed resources in Resource Manager, and both organizations and folders act as policy inheritance points for everything below them (<a href="https://docs.cloud.google.com/resource-manager/docs/overview" target="_blank" rel="noreferrer">About resource hierarchy</a>).</p><p>Folders can be nested up to 10 levels deep, and a single parent folder cannot directly contain more than 300 child folders (<a href="https://docs.cloud.google.com/resource-manager/docs/limits" target="_blank" rel="noreferrer">Project limits</a>).</p><p>A project does not require an organization above it. A project can sit at the top of its own hierarchy, with no organization or folder as an ancestor, when it is created by a free trial or free tier user; such a project can later be migrated into an organization&#39;s hierarchy once one exists for the relevant domain (<a href="https://docs.cloud.google.com/resource-manager/docs/overview" target="_blank" rel="noreferrer">About resource hierarchy</a>).</p><h2 id="governance-and-work" tabindex="-1">Governance and work <a class="header-anchor" href="#governance-and-work" aria-label="Permalink to &quot;Governance and work&quot;">​</a></h2><p>The organization is the root policy inheritance point for both IAM allow and deny policies and for Organization Policy Service constraints, reaching every folder and project beneath it by default (<a href="https://docs.cloud.google.com/iam/docs/resource-hierarchy-access-control" target="_blank" rel="noreferrer">Using resource hierarchy for access control</a>; <a href="https://docs.cloud.google.com/resource-manager/docs/overview" target="_blank" rel="noreferrer">About resource hierarchy</a>). Projects are where the actual work happens: enabling APIs, creating resources, and managing collaborators (<a href="https://docs.cloud.google.com/resource-manager/docs/overview" target="_blank" rel="noreferrer">About resource hierarchy</a>).</p><p>Billing runs through a parallel structure rather than the same ownership chain. A Cloud Billing account defines who pays and can be linked to one or more projects, while each project links to exactly one billing account at a time; the organization owns a project for IAM purposes, but the billing account merely pays for it and can belong to a different organization, inheriting IAM permissions from its own parent organization rather than the project&#39;s (<a href="https://docs.cloud.google.com/billing/docs/concepts" target="_blank" rel="noreferrer">Overview of Cloud Billing concepts</a>). A project without an active linked billing account cannot use billable Google Cloud services (<a href="https://docs.cloud.google.com/billing/docs/concepts" target="_blank" rel="noreferrer">Overview of Cloud Billing concepts</a>).</p><h2 id="audiences-and-visibility" tabindex="-1">Audiences and visibility <a class="header-anchor" href="#audiences-and-visibility" aria-label="Permalink to &quot;Audiences and visibility&quot;">​</a></h2><p>Google Cloud IAM does not document a named audience ladder, such as public, organization-wide, or invited-members, for organizations, folders, or projects as a whole. Access is granted through IAM allow policy bindings naming specific principals: individual accounts, groups, domains, service accounts, or one of two special identifiers. <code>allUsers</code> represents anyone on the internet, with or without a Google account, and <code>allAuthenticatedUsers</code> represents anyone authenticated with a Google account or service account, excluding identities federated from an external identity provider (<a href="https://docs.cloud.google.com/iam/docs/principal-identifiers" target="_blank" rel="noreferrer">Principal identifiers</a>). These identifiers behave as a public-style grant wherever a binding accepts them, rather than as a configurable audience setting attached to the hierarchy itself.</p><h2 id="narrowing-below-a-parent" tabindex="-1">Narrowing below a parent <a class="header-anchor" href="#narrowing-below-a-parent" aria-label="Permalink to &quot;Narrowing below a parent&quot;">​</a></h2><p>IAM allow policy inheritance is additive only: the effective allow policy on a resource is the union of its own policy and every ancestor&#39;s policy, and nothing in an allow policy can revoke a grant made higher up (<a href="https://docs.cloud.google.com/iam/docs/resource-hierarchy-access-control" target="_blank" rel="noreferrer">Using resource hierarchy for access control</a>). Narrowing access below an ancestor&#39;s grant instead requires an IAM deny policy, attached at the organization, folder, or project level, never to an individual resource. Deny policies are inherited by everything below the point where they are attached, and IAM always evaluates applicable deny policies before applicable allow policies, so a deny rule blocks a permission regardless of any role granted above it. This is documented as the intended pattern for granting a role broadly and then excluding it for a narrower scope beneath that grant (<a href="https://docs.cloud.google.com/iam/docs/deny-overview" target="_blank" rel="noreferrer">Deny policies</a>).</p><p>Organization Policy Service constraints offer a second, narrower form of restriction. For list constraints, a parent&#39;s explicit <code>DENY</code> values always take precedence during merging, so a child cannot permit a value its parent has denied, while a child can still shrink an allow-list further than its parent did (<a href="https://docs.cloud.google.com/organization-policy/hierarchy-evaluation" target="_blank" rel="noreferrer">Hierarchy evaluation</a>).</p><h2 id="ceilings-from-above" tabindex="-1">Ceilings from above <a class="header-anchor" href="#ceilings-from-above" aria-label="Permalink to &quot;Ceilings from above&quot;">​</a></h2><p>Organization Policy constraints are set at the organization, folder, or project and, by default, are inherited by every descendant (<a href="https://docs.cloud.google.com/resource-manager/docs/organization-policy/understanding-policies" target="_blank" rel="noreferrer">Understanding organization policies</a>). For list constraints with inheritance enabled, a parent&#39;s <code>DENY</code> values always win when merged with a child&#39;s configuration, so those act as a true ceiling a child cannot remove (<a href="https://docs.cloud.google.com/organization-policy/hierarchy-evaluation" target="_blank" rel="noreferrer">Hierarchy evaluation</a>). Boolean constraints behave differently: if a child resource sets its own explicit policy, that value is used for the child&#39;s effective policy instead of the inherited one, so a project can set <code>enforced: false</code> to turn off a constraint its parent folder enforces as <code>enforced: true</code>, unless the constraint is a managed constraint, which Google documents as not merged with an inherited parent value at all and therefore not overridable the same way (<a href="https://docs.cloud.google.com/organization-policy/hierarchy-evaluation" target="_blank" rel="noreferrer">Hierarchy evaluation</a>). This means Organization Policy ceilings are opt-in and constraint dependent rather than uniformly absolute: whether a descendant can loosen what an ancestor set depends on the specific constraint&#39;s type and whether it is a managed constraint.</p><p>IAM deny policies are a stronger ceiling in comparison: once attached at a level, nothing documented allows a descendant to remove or override that inherited deny rule (<a href="https://docs.cloud.google.com/iam/docs/deny-overview" target="_blank" rel="noreferrer">Deny policies</a>).</p><h2 id="discovery-versus-access" tabindex="-1">Discovery versus access <a class="header-anchor" href="#discovery-versus-access" aria-label="Permalink to &quot;Discovery versus access&quot;">​</a></h2><p>Google Cloud does not document a separate discovery state in which a principal can see that an organization, folder, or project exists without already holding access to it. Reading a project&#39;s own metadata requires the <code>resourcemanager.projects.get</code> permission on that specific project; the same permission check governs both knowing the project exists through the API or console and reading its details (<a href="https://docs.cloud.google.com/resource-manager/reference/rest/v3/projects/get" target="_blank" rel="noreferrer">Method: projects.get</a>).</p><h2 id="small-customers" tabindex="-1">Small customers <a class="header-anchor" href="#small-customers" aria-label="Permalink to &quot;Small customers&quot;">​</a></h2><p>A project can be created and used without any organization above it at all; this is documented for free trial and free tier users, whose projects sit at the top of their own hierarchy with no organization or folder ancestor (<a href="https://docs.cloud.google.com/resource-manager/docs/overview" target="_blank" rel="noreferrer">About resource hierarchy</a>). Such a project still needs its own linked billing account to use billable services, but that billing account is a separate resource from the organization and does not require one to exist (<a href="https://docs.cloud.google.com/billing/docs/concepts" target="_blank" rel="noreferrer">Overview of Cloud Billing concepts</a>).</p><h2 id="consolidation" tabindex="-1">Consolidation <a class="header-anchor" href="#consolidation" aria-label="Permalink to &quot;Consolidation&quot;">​</a></h2><p>Moving an individual project is supported and documented as a metadata operation: a project can migrate from one organization to another, or a standalone project with no organization can be migrated into an organization&#39;s hierarchy, without transferring data or causing downtime to the project&#39;s running resources (<a href="https://docs.cloud.google.com/resource-manager/docs/project-migration" target="_blank" rel="noreferrer">Migrating projects between organization resources</a>). Migration requires the Project IAM Admin role on the project and the Project Mover role on the destination, and both the source and destination organizations must explicitly allow the export and import through their own organization policy settings before a migration can proceed; moving a project back to having no organization at all is not self-service and requires contacting Cloud customer support (<a href="https://docs.cloud.google.com/resource-manager/docs/project-migration" target="_blank" rel="noreferrer">Migrating projects between organization resources</a>).</p><p>There is no documented tool that merges two Google Cloud organization resources into one. The adjacent operation, merging domains from separate Google Workspace or Cloud Identity accounts, is a manual process: data must be exported first, all but one account must be canceled and deleted, and the deletion of an account from the Admin console is permanent and cannot be undone (<a href="https://knowledge.workspace.google.com/admin/domains/merge-domains-from-separate-accounts" target="_blank" rel="noreferrer">Merge domains from separate accounts</a>). Merging the identity layer this way does not by itself touch the separate Google Cloud organization resources tied to each original account; consolidating the resource hierarchies still requires moving projects individually.</p><h2 id="relevance-to-this-adr" tabindex="-1">Relevance to this ADR <a class="header-anchor" href="#relevance-to-this-adr" aria-label="Permalink to &quot;Relevance to this ADR&quot;">​</a></h2><ul><li>Google Cloud&#39;s three typed levels line up closely with the ADR&#39;s vocabulary: organization as the governing root, folder as an optional nested grouping, and project as the place work actually lives, matching the ADR&#39;s claim that folders are optional and that work attaches at or below the first level under the root.</li><li>The ADR&#39;s rule that ancestors&#39; limits cap descendants holds for IAM deny policies and for list-type Organization Policy constraints, where a parent&#39;s denied values are documented as always winning. It does not hold uniformly for boolean Organization Policy constraints, where a child can set its own value and have it replace, rather than be capped by, what a parent enforced, unless the constraint is a managed constraint that is not overridden this way.</li><li>The ADR models grants as strictly additive and narrowing as a separate limit mechanism; Google Cloud&#39;s IAM allow policies match the additive half exactly, and IAM deny policies, attached at an organization, folder, or project and never to an individual resource, match the ADR&#39;s narrowing half closely.</li><li>Google Cloud projects without an organization, available to free trial and free tier users, match the ADR&#39;s goal of a small customer never meeting the governing layer, though Google Cloud reaches this by omitting the organization resource entirely rather than by hiding an organization that already exists underneath, as the ADR&#39;s one-workspace reveal model does.</li><li>Google Cloud&#39;s documented absence of an organization merge tool, with project migration as the only supported consolidation path, agrees with the ADR&#39;s position that separately created top-level entities consolidate only through an explicit migration rather than an ordinary tree operation.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://docs.cloud.google.com/resource-manager/docs/overview" target="_blank" rel="noreferrer">About resource hierarchy</a></li><li><a href="https://docs.cloud.google.com/resource-manager/docs/limits" target="_blank" rel="noreferrer">Project limits</a></li><li><a href="https://docs.cloud.google.com/iam/docs/resource-hierarchy-access-control" target="_blank" rel="noreferrer">Using resource hierarchy for access control</a></li><li><a href="https://docs.cloud.google.com/iam/docs/principal-identifiers" target="_blank" rel="noreferrer">Principal identifiers</a></li><li><a href="https://docs.cloud.google.com/iam/docs/deny-overview" target="_blank" rel="noreferrer">Deny policies</a></li><li><a href="https://docs.cloud.google.com/resource-manager/docs/organization-policy/understanding-policies" target="_blank" rel="noreferrer">Understanding organization policies</a></li><li><a href="https://docs.cloud.google.com/organization-policy/hierarchy-evaluation" target="_blank" rel="noreferrer">Hierarchy evaluation</a></li><li><a href="https://docs.cloud.google.com/billing/docs/concepts" target="_blank" rel="noreferrer">Overview of Cloud Billing concepts</a></li><li><a href="https://docs.cloud.google.com/resource-manager/reference/rest/v3/projects/get" target="_blank" rel="noreferrer">Method: projects.get</a></li><li><a href="https://docs.cloud.google.com/resource-manager/docs/project-migration" target="_blank" rel="noreferrer">Migrating projects between organization resources</a></li><li><a href="https://knowledge.workspace.google.com/admin/domains/merge-domains-from-separate-accounts" target="_blank" rel="noreferrer">Merge domains from separate accounts</a></li></ul>',28)])])}const p=a(n,[["render",i]]);export{u as __pageData,p as default};
